<?php
require __DIR__ . '/../functions.php'; global $config; $lang = current_lang();
if (isset($_GET['logout'])) { unset($_SESSION['is_admin']); header('Location: index.php?lang=' . $lang); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); if (($_POST['action'] ?? '') === 'login' && hash_equals($config['admin_user'], $_POST['username'] ?? '') && hash_equals($config['admin_password'], $_POST['password'] ?? '')) { $_SESSION['is_admin'] = true; header('Location: index.php?lang=' . $lang); exit; } if (($_POST['action'] ?? '') === 'login') $error = 'Invalid login.'; if (is_admin() && ($_POST['action'] ?? '') === 'save') { db()->prepare('UPDATE products SET price = ?, stock = ?, active = ? WHERE id = ?')->execute([(float)$_POST['price'], (int)$_POST['stock'], isset($_POST['active']) ? 1 : 0, (int)$_POST['id']]); } if (is_admin() && ($_POST['action'] ?? '') === 'status') db()->prepare('UPDATE orders SET status = ? WHERE id = ?')->execute([$_POST['status'], (int)$_POST['id']]); }
?><!doctype html><html lang="<?= $lang ?>" dir="<?= $lang === 'ar' ? 'rtl' : 'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= text('admin') ?> | Lissi</title><link rel="stylesheet" href="../style.css"></head><body><main class="section shell"><header class="admin-head"><a class="brand" href="../index.php"><img src="../assets/logo.jpeg" alt="Lissi"><span>LISSI / <?= text('admin') ?></span></a><div class="header-tools"><a href="?lang=ar">ع</a><a href="?lang=fr">FR</a><a href="?lang=en">EN</a><button class="theme-toggle" type="button" data-theme-toggle>◐</button><?php if (is_admin()): ?><a class="logout" href="?logout=1&lang=<?= $lang ?>">↪ <?= text('logout') ?></a><?php endif; ?></div></header><?php if (!is_admin()): ?><h2><?= text('login') ?></h2><?php if ($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="login"><label>Username<input name="username" required></label><label>Password<input name="password" type="password" required></label><button class="dark"><?= text('login') ?></button></form><?php else: ?><div class="dashboard-title"><div><p class="eyebrow">Lissi control room</p><h2><?= text('admin') ?></h2></div><div class="stats"><b><?= db()->query("SELECT COUNT(*) FROM orders")->fetchColumn() ?><small><?= text('orders') ?></small></b><b><?= db()->query("SELECT COUNT(*) FROM products WHERE active = 1")->fetchColumn() ?><small><?= text('inventory') ?></small></b></div></div><section class="admin-section"><h3><?= text('orders') ?></h3><?php $orders = db()->query('SELECT * FROM orders ORDER BY created_at DESC')->fetchAll(); if (!$orders): ?><p class="muted">No orders yet.</p><?php else: ?><?php foreach ($orders as $order): ?><article class="order-card"><div><b>#<?= $order['id'] ?> · <?= e($order['full_name']) ?></b><span><?= e($order['phone']) ?> · <?= e($order['wilaya']) ?> / <?= e($order['commune']) ?></span><span><?= e($order['delivery_method']) ?> · <?= money($order['total']) ?> · <?= e($order['created_at']) ?></span></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= $order['id'] ?>"><select name="status" onchange="this.form.submit()"><option <?= $order['status'] === 'New' ? 'selected' : '' ?>>New</option><option <?= $order['status'] === 'Confirmed' ? 'selected' : '' ?>>Confirmed</option><option <?= $order['status'] === 'Shipped' ? 'selected' : '' ?>>Shipped</option><option <?= $order['status'] === 'Cancelled' ? 'selected' : '' ?>>Cancelled</option></select></form></article><?php endforeach; ?><?php endif; ?></section><section class="admin-section"><h3><?= text('inventory') ?></h3><?php foreach (db()->query('SELECT * FROM products ORDER BY id DESC') as $product): ?><form class="line admin-product" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= $product['id'] ?>"><div class="art" style="background:<?= e($product['image_color']) ?>"><strong><?= e($product['short_name']) ?></strong></div><div><b><?= e($product['name']) ?></b><span>Stock <input name="stock" type="number" min="0" value="<?= $product['stock'] ?>"> Price <input name="price" type="number" min="0" value="<?= $product['price'] ?>"></span></div><label>Active <input name="active" type="checkbox" <?= $product['active'] ? 'checked' : '' ?>></label><button class="dark"><?= text('save') ?></button></form><?php endforeach; ?></section><?php endif; ?></main><script>const toggle=document.querySelector('[data-theme-toggle]');const saved=localStorage.getItem('lissi-theme');if(saved)document.documentElement.dataset.theme=saved;toggle?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('lissi-theme',next)});</script></body></html>
